<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atendimento IA</title><style>
*{box-sizing:border-box}body{margin:0;background:#e9edef;font-family:Arial,sans-serif}.app{height:100dvh;max-width:900px;margin:auto;background:#efeae2;display:flex;flex-direction:column}.top{height:64px;background:#075e54;color:#fff;display:flex;align-items:center;padding:8px 15px;gap:12px}.ava{width:44px;height:44px;border-radius:50%;background:#25d366;display:grid;place-items:center;font-weight:bold}.top small{display:block;opacity:.8}.top a{margin-left:auto;color:white;text-decoration:none;font-size:12px}.msgs{flex:1;overflow:auto;padding:18px}.msg{max-width:78%;padding:10px 13px;margin:7px 0;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere}.in{background:#fff}.out{background:#d9ffc7;margin-left:auto}.bar{display:flex;padding:9px;background:#f0f2f5;gap:8px}.bar input,.form input{flex:1;border:0;border-radius:24px;padding:13px}.bar button,.form button{border:0;border-radius:50%;width:48px;background:#25d366;color:white;font-size:20px}.form{position:fixed;inset:0;background:#0008;display:grid;place-items:center}.box{background:white;width:min(430px,92%);padding:25px;border-radius:18px}.box input{width:100%;padding:13px;margin:6px 0;border:1px solid #ddd;border-radius:10px}.box button{width:100%;padding:13px;background:#25d366;color:white;border:0;border-radius:10px;font-weight:bold}.hidden{display:none!important}.typing{padding:4px 18px;color:#667781;font-size:12px}
</style></head><body><div class="app"><header class="top"><div class="ava">IA</div><div><b>Atendimento IA</b><small>online</small></div><a href="admin.php">Admin</a></header><main id="msgs" class="msgs"></main><div id="typing" class="typing hidden">IA está digitando…</div><form id="bar" class="bar"><input id="text" placeholder="Digite uma mensagem..." maxlength="4000"><button>➤</button></form></div>
<div id="register" class="form"><div class="box"><h2>Iniciar atendimento</h2><input id="name" placeholder="Nome"><input id="phone" placeholder="Telefone / WhatsApp"><input id="email" placeholder="E-mail (opcional)"><input id="sid" placeholder="Usuário ou ID do sistema (opcional)"><label><input type="checkbox" id="ok"> Concordo com o uso dos dados para atendimento.</label><button id="start">Continuar</button><p>Não informe senhas, tokens ou códigos de segurança.</p></div></div>
<script>
let cid=null;
const $=x=>document.getElementById(x);
function msg(t,c){let d=document.createElement('div');d.className='msg '+c;d.textContent=t;$('msgs').appendChild(d);$('msgs').scrollTop=$('msgs').scrollHeight}
async function api(u,d){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),j=await r.json();if(!r.ok)throw Error(j.error||'Erro');return j}
$('start').onclick=async()=>{if(!$('ok').checked)return alert('Aceite o consentimento.');try{let j=await api('api.php',{action:'start',name:$('name').value,phone:$('phone').value,email:$('email').value,system_id:$('sid').value});cid=j.id;$('register').classList.add('hidden');j.messages.forEach(x=>msg(x.text,x.role==='assistant'?'in':'out'))}catch(e){alert(e.message)}};
$('bar').onsubmit=async e=>{e.preventDefault();let t=$('text').value.trim();if(!t||!cid)return;$('text').value='';msg(t,'out');$('typing').classList.remove('hidden');try{let j=await api('api.php',{action:'chat',id:cid,message:t});msg(j.reply,'in')}catch(e){msg(e.message,'in')}finally{$('typing').classList.add('hidden')}};
</script></body></html>